#[no_mangle]
pub extern "C" fn jaro_winkler(v:*const i64,n:usize)->f64{const BAD:f64=-1e300;if v.is_null()||n<2||n>66{return BAD;}let v=unsafe{std::slice::from_raw_parts(v,n)};let n1=v[0];if !(0..=32).contains(&n1)||1+n1 as usize>=n{return BAD;}let p2=1+n1 as usize;let n2=v[p2];if !(0..=32).contains(&n2)||n!=p2+1+n2 as usize{return BAD;}let a=&v[1..p2];let b=&v[p2+1..];if a.iter().chain(b).any(|&x|!(0..=127).contains(&x)){return BAD;}let r=std::cmp::min(n1,n2)/2;let mut u2=[false;32];let mut ma=[0i64;32];let mut ca=0;for(i,&x)in a.iter().enumerate(){let lo=0.max(i as i64-r)as usize;let hi=(i as i64+r+1).min(n2)as usize;for j in lo..hi{if !u2[j]&&x==b[j]{u2[j]=true;ma[ca]=x;ca+=1;break;}}}let mut u1=[false;32];let mut mb=[0i64;32];let mut cb=0;for(i,&x)in b.iter().enumerate(){let lo=0.max(i as i64-r)as usize;let hi=(i as i64+r+1).min(n1)as usize;for j in lo..hi{if !u1[j]&&x==a[j]{u1[j]=true;mb[cb]=x;cb+=1;break;}}}let trans=(0..ca.min(cb)).filter(|&i|ma[i]!=mb[i]).count()/2;let mut jr=0.0;if ca>0{jr=(ca as f64/n1 as f64+ca as f64/n2 as f64+(ca as f64-trans as f64)/ca as f64)/3.0;}let prefix=a.iter().zip(b).take(4).take_while(|(x,y)|x==y).count();jr+0.1*prefix as f64*(1.0-jr)}
